    {
      "fact_text": {
        "text": "Java integer literals are interpreted as int by default, which can store values up to about two billion.",
        "refs": ["Q0000"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "If an integer literal exceeds the int range, the compiler reports \"integer number too large\" unless the literal is suffixed with L to indicate a long.",
        "refs": ["Q0000", "Q0001"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "Java decimal literals are interpreted as double by default.",
        "refs": ["Q0002"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "Assigning a double literal to a float variable without a suffix causes a compilation error: \"incompatible types: required float, found double\".",
        "refs": ["Q0002"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "All primitive type keywords (e.g., int, long, float, double, char, boolean) are reserved and cannot be used as identifiers.",
